import React, { useState } from 'react';

const Dashboard = ({ onNavigate }) => {
  const [pnrInput, setPnrInput] = useState('');
  const [isCalling, setIsCalling] = useState(false); // State for the popup
  const [flights, setFlights] = useState([
    { flight: 'AI-202', to: 'Hyderabad (HYD)', departs: '10:30 AM', gate: 'T3-A12', status: 'BOARDING' },
    { flight: '6E-501', to: 'Vijayawada (VGA)', departs: '02:30 PM', gate: 'T1-04', status: 'ON-TIME' },
  ]);

  const amenities = [
    { name: 'Duty Free Luxe (T3)', emoji: '🛍️' },
    { name: 'Starbucks Reserve', emoji: '☕' },
    { name: 'Plaza Premium Lounge', emoji: '🛋️' },
    { name: 'Global Food Court', emoji: '🍲' },
    { name: 'Reliance Digital', emoji: '🔌' },
    { name: 'Hamleys Toys', emoji: '🧸' }
  ];

  const handleTrack = async () => {
    const res = await fetch(`http://localhost:5000/get-pnr/${pnrInput.toUpperCase()}`);
    if (res.ok) {
      const data = await res.json();
      setFlights([data, ...flights]);
    } else { alert("PNR not found."); }
  };

  const initiateCall = async () => {
    setIsCalling(true); // Show popup immediately
    try {
      await fetch('http://localhost:5000/make-call', { method: 'POST' });
      // Auto-hide popup after 4 seconds
      setTimeout(() => setIsCalling(false), 4000);
    } catch (err) {
      setIsCalling(false);
      alert("Call failed to initiate.");
    }
  };

  return (
    <div style={{ background: '#f8fafc', height: '100vh', display: 'flex', fontFamily: 'Inter, sans-serif', position: 'relative' }}>

      {/* CALL INITIATED POPUP */}
      {isCalling && (
        <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(10, 25, 49, 0.7)', zIndex: 1000, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <div style={{ background: 'white', padding: '40px', borderRadius: '24px', textAlign: 'center', boxShadow: '0 20px 50px rgba(0,0,0,0.3)', border: '2px solid #1d4ed8' }}>
            <div style={{ fontSize: '50px', marginBottom: '20px' }}>📞</div>
            <h2 style={{ color: '#0a1931', margin: '0 0 10px 0' }}>Call Initiated</h2>
            <p style={{ color: '#64748b', fontSize: '14px' }}>Connecting you to SkySync AI Support...<br/>Please check your mobile device.</p>
            <button onClick={() => setIsCalling(false)} style={{ marginTop: '20px', padding: '10px 25px', borderRadius: '12px', border: '1px solid #ddd', background: '#f8fafc', cursor: 'pointer' }}>Dismiss</button>
          </div>
        </div>
      )}

      {/* SIDEBAR - All layout preserved */}
      <div style={{ width: '260px', background: '#0a1931', color: '#cbd5e1', padding: '25px', display: 'flex', flexDirection: 'column' }}>
        <b style={{ color: '#fbbf24', fontSize: '20px', marginBottom: '35px' }}>✈️ SkySync</b>

        <h5 style={{ color: '#94a3b8', fontSize: '11px', textTransform: 'uppercase', marginBottom: '15px' }}>Airport Amenities</h5>
        {amenities.map(a => (
          <div key={a.name} style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '12px 0', fontSize: '12px', borderBottom: '1px solid #1e293b' }}>
            <span>{a.emoji}</span> {a.name}
          </div>
        ))}

        <div style={{ flex: 1 }}></div>

        <button onClick={initiateCall} style={{ background: '#1d4ed8', color: 'white', border: 'none', padding: '14px', borderRadius: '8px', cursor: 'pointer', marginBottom: '10px', fontWeight: 'bold', fontSize: '12px' }}>📞 Voice Call</button>
        <button onClick={() => onNavigate('voiceweb')} style={{ background: '#10b981', color: 'white', border: 'none', padding: '14px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' }}>🌐 Voice Web</button>
      </div>

      <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {/* Main tracking header */}
        <div style={{ background: '#1d4ed8', color: 'white', padding: '60px', textAlign: 'center' }}>
          <h1 style={{ fontSize: '32px' }}>Welcome to SkySync</h1>
          <div style={{ display: 'flex', gap: '10px', background: 'white', padding: '8px', borderRadius: '12px', maxWidth: '550px', margin: '25px auto 0' }}>
            <input value={pnrInput} onChange={(e) => setPnrInput(e.target.value)} placeholder="Enter PNR (e.g., SKY1234)" style={{ flex: 1, padding: '12px', border: 'none', outline: 'none', color: '#333' }} />
            <button onClick={handleTrack} style={{ background: '#059669', color: 'white', border: 'none', padding: '0 25px', borderRadius: '8px', fontWeight: 'bold' }}>TRACK</button>
          </div>
        </div>
        {/* Table layout preserved */}
        <div style={{ padding: '40px 60px' }}>
          <b style={{ color: '#0a1931', fontSize: '18px' }}>Live Departures</b>
          <table style={{ width: '100%', borderCollapse: 'collapse', background: 'white', marginTop: '20px', border: '1px solid #e2e8f0', borderRadius: '12px', overflow: 'hidden' }}>
            <thead style={{ background: '#f1f5f9', textAlign: 'left', fontSize: '10px' }}>
              <tr><th style={{ padding: '18px' }}>Flight</th><th style={{ padding: '18px' }}>To</th><th style={{ padding: '18px' }}>Departs</th><th style={{ padding: '18px' }}>Status</th></tr>
            </thead>
            <tbody style={{ fontSize: '13px' }}>
              {flights.map((f, i) => (
                <tr key={i} style={{ borderBottom: '1px solid #f1f5f9' }}>
                  <td style={{ padding: '18px', fontWeight: 'bold' }}>{f.flight}</td>
                  <td style={{ padding: '18px' }}>{f.to}</td>
                  <td style={{ padding: '18px' }}>{f.departs}</td>
                  <td style={{ padding: '18px' }}><span style={{ background: '#dcfce7', color: '#15803d', padding: '5px 12px', borderRadius: '20px', fontWeight: 'bold' }}>{f.status}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
